"use client"

import * as React from "react"
import { ChevronDown } from "lucide-react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { DeltaBadge } from "@/registry/dashboardcn/ui/delta-badge"
import { FunnelChart, type FunnelChartProps, type FunnelStep } from "@/registry/dashboardcn/ui/funnel-chart"
import { MetricValue } from "@/registry/dashboardcn/ui/metric-value"

export interface FunnelRange {
  value: string
  label: string
  /** Top of the funnel first. */
  steps: FunnelStep[]
  /** Change in the first step vs the previous range, as a fraction. */
  delta?: number
}

export interface FunnelChartCardProps
  extends Omit<React.ComponentProps<typeof Card>, "children"> {
  title: string
  /** Top of the funnel first. Ignored when `ranges` is set. */
  steps?: FunnelStep[]
  /** Change in the first step, as a fraction. Ignored when `ranges` is set. */
  delta?: number
  /** Context for the delta, e.g. "vs last week". */
  deltaLabel?: string
  invertDelta?: boolean
  /** Static text in the header, e.g. "Last 30 days". Replaced by the picker when `ranges` is set. */
  caption?: string
  /** Ranges for the header picker. Each carries its own steps. */
  ranges?: FunnelRange[]
  range?: string
  defaultRange?: string
  onRangeChange?: (value: string) => void
  format?: NumberFormat
  currency?: string
  color?: FunnelChartProps["color"]
  shape?: FunnelChartProps["shape"]
  height?: FunnelChartProps["height"]
  neckWidth?: FunnelChartProps["neckWidth"]
  showPercentages?: FunnelChartProps["showPercentages"]
  showLabels?: FunnelChartProps["showLabels"]
  chartClassName?: string
}

/** A conversion card with a flow funnel: headline value, delta, and a range picker. Hovering a stage swaps the headline to that stage. */
function FunnelChartCard({
  title,
  steps: stepsProp = [],
  delta: deltaProp,
  deltaLabel,
  invertDelta,
  caption,
  ranges,
  range: rangeProp,
  defaultRange,
  onRangeChange,
  format = "number",
  currency,
  color,
  shape,
  height,
  neckWidth,
  showPercentages,
  showLabels,
  chartClassName,
  className,
  ...props
}: FunnelChartCardProps) {
  const [rangeState, setRangeState] = React.useState(defaultRange ?? ranges?.[0]?.value)
  const range = rangeProp ?? rangeState
  const setRange = (value: string) => {
    setRangeState(value)
    onRangeChange?.(value)
  }
  const current = ranges?.find((option) => option.value === range) ?? ranges?.[0]
  const steps = current?.steps ?? stepsProp
  const delta = current ? current.delta : deltaProp

  const [active, setActive] = React.useState<number | null>(null)
  const first = steps[0]
  const hovered = active !== null ? steps[active] : undefined
  const headline = hovered ?? first
  const share = hovered && first && first.value > 0 ? hovered.value / first.value : null

  const valueFormatter = React.useCallback(
    (value: number) => formatNumber(value, { format, currency }),
    [format, currency]
  )

  return (
    <Card data-slot="funnel-chart-card" className={cn("gap-4", className)} {...props}>
      <CardHeader>
        <CardDescription>{title}</CardDescription>
        <CardTitle className="text-3xl font-semibold tabular-nums tracking-tight">
          <MetricValue value={headline?.value ?? 0} format={format} currency={currency} />
        </CardTitle>
        <div className="flex h-5 items-center gap-1.5 text-sm">
          {hovered && share !== null ? (
            <span className="text-muted-foreground truncate">
              {hovered.name}
              {hovered !== first ? (
                <>
                  {" · "}
                  <span className="text-foreground font-medium tabular-nums">
                    {formatNumber(share, { format: "percent", maximumFractionDigits: 0 })}
                  </span>{" "}
                  of {first?.name}
                </>
              ) : null}
            </span>
          ) : (
            <>
              {delta !== undefined ? (
                <DeltaBadge delta={delta} invert={invertDelta} variant="soft" />
              ) : null}
              {deltaLabel ? <span className="text-muted-foreground">{deltaLabel}</span> : null}
            </>
          )}
        </div>
        {ranges?.length ? (
          <CardAction>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm">
                  {current?.label}
                  <ChevronDown className="text-muted-foreground" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuRadioGroup value={range} onValueChange={setRange}>
                  {ranges.map((option) => (
                    <DropdownMenuRadioItem key={option.value} value={option.value}>
                      {option.label}
                    </DropdownMenuRadioItem>
                  ))}
                </DropdownMenuRadioGroup>
              </DropdownMenuContent>
            </DropdownMenu>
          </CardAction>
        ) : caption ? (
          <CardAction>
            <span className="text-muted-foreground text-sm">{caption}</span>
          </CardAction>
        ) : null}
      </CardHeader>
      <CardContent>
        <FunnelChart
          variant="flow"
          steps={steps}
          valueFormatter={valueFormatter}
          color={color}
          shape={shape}
          height={height}
          neckWidth={neckWidth}
          showPercentages={showPercentages}
          showLabels={showLabels}
          activeIndex={active}
          onActiveIndexChange={setActive}
          className={chartClassName}
        />
      </CardContent>
    </Card>
  )
}

export { FunnelChartCard }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatNumber } from "@/registry/dashboardcn/lib/format"

export interface FunnelStep {
  name: string
  value: number
  /** Any CSS color for this step in the flow variant. Defaults to chart-1 through chart-5 in order. */
  color?: string
}

export interface FunnelChartProps extends React.ComponentProps<"div"> {
  steps: FunnelStep[]
  valueFormatter?: (value: number) => string
  /**
   * Any CSS color. "bars" fades it step by step. "flow" paints every stage in
   * it, in place of the per-stage palette.
   */
  color?: string
  /** Show the drop-off between consecutive steps. Bars only. */
  showDropoff?: boolean
  /** "bars" stacks one bar per step; "flow" runs the steps left to right, each tapering into the next. */
  variant?: "bars" | "flow"
  /** Flow only. "eased" curves each neck; "sharp" draws straight trapezoids. */
  shape?: "eased" | "sharp"
  /** Flow only. Height of the stages in pixels. */
  height?: number
  /** Flow only. Width of the neck between stages in pixels. */
  neckWidth?: number
  /** Flow only. Show the share of the first step as a pill on each stage. */
  showPercentages?: boolean
  /** Flow only. Show a tile with the name and value under each stage. */
  showLabels?: boolean
  /** Flow only. Stage drawn at full strength while the rest dim. */
  activeIndex?: number | null
  onActiveIndexChange?: (index: number | null) => void
}

const defaultColors = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
]

// Round so server and client render identical path strings.
const round = (n: number) => Math.round(n * 1000) / 1000

/** Path for the neck between two stages, in a 1x1 box stretched to fit. */
function neckPath(from: number, to: number, shape: "eased" | "sharp") {
  const t0 = round((1 - from) / 2)
  const b0 = round(1 - t0)
  const t1 = round((1 - to) / 2)
  const b1 = round(1 - t1)
  if (shape === "sharp") return `M0,${t0} L1,${t1} L1,${b1} L0,${b0} Z`
  return `M0,${t0} C0.5,${t0} 0.5,${t1} 1,${t1} L1,${b1} C0.5,${b1} 0.5,${b0} 0,${b0} Z`
}

function FunnelBars({
  steps,
  valueFormatter,
  color,
  showDropoff,
}: {
  steps: FunnelStep[]
  valueFormatter: (value: number) => string
  color: string
  showDropoff: boolean
}) {
  const first = steps[0]?.value ?? 0
  const last = steps[steps.length - 1]?.value ?? 0
  const overall = first > 0 ? last / first : 0

  return (
    <>
      {steps.map((step, index) => {
        const previous = index > 0 ? steps[index - 1]!.value : step.value
        const ofFirst = first > 0 ? step.value / first : 0
        const ofPrevious = previous > 0 ? step.value / previous : 0
        const dropoff = 1 - ofPrevious

        return (
          <React.Fragment key={step.name}>
            {showDropoff && index > 0 ? (
              <div className="text-muted-foreground flex items-center gap-2 py-1 pl-3 text-xs">
                <span aria-hidden="true" className="bg-border h-3 w-px" />
                <span className="tabular-nums">
                  {formatNumber(dropoff, { format: "percent" })} drop-off
                </span>
              </div>
            ) : null}
            <div data-slot="funnel-step" className="flex flex-col gap-1.5">
              <div className="flex items-baseline justify-between gap-4 text-sm">
                <span className="flex items-center gap-2 truncate">
                  <span className="text-muted-foreground w-4 shrink-0 text-xs tabular-nums">
                    {index + 1}
                  </span>
                  <span className="truncate font-medium">{step.name}</span>
                </span>
                <span className="flex shrink-0 items-baseline gap-2 tabular-nums">
                  <span className="font-medium">{valueFormatter(step.value)}</span>
                  <span className="text-muted-foreground w-12 text-right text-xs">
                    {formatNumber(ofFirst, { format: "percent" })}
                  </span>
                </span>
              </div>
              <div className="bg-muted h-6 w-full overflow-hidden rounded-md">
                <div
                  className="h-full rounded-md transition-[width] duration-300"
                  style={{
                    width: `${ofFirst * 100}%`,
                    backgroundColor: color,
                    opacity: 1 - index * (0.5 / Math.max(steps.length - 1, 1)),
                  }}
                />
              </div>
            </div>
          </React.Fragment>
        )
      })}
      {steps.length > 1 ? (
        <div className="mt-2 flex items-center justify-between border-t pt-3 text-sm">
          <span className="text-muted-foreground">Overall conversion</span>
          <span className="font-semibold tabular-nums">
            {formatNumber(overall, { format: "percent" })}
          </span>
        </div>
      ) : null}
    </>
  )
}

function FunnelFlow({
  steps,
  valueFormatter,
  color,
  shape,
  height,
  neckWidth,
  showPercentages,
  showLabels,
  activeIndex,
  onActiveIndexChange,
}: {
  steps: FunnelStep[]
  valueFormatter: (value: number) => string
  color?: string
  shape: "eased" | "sharp"
  height: number
  neckWidth: number
  showPercentages: boolean
  showLabels: boolean
  activeIndex?: number | null
  onActiveIndexChange?: (index: number | null) => void
}) {
  const id = React.useId()
  const [activeState, setActiveState] = React.useState<number | null>(null)
  const active = activeIndex === undefined ? activeState : activeIndex
  const setActive = (index: number | null) => {
    setActiveState(index)
    onActiveIndexChange?.(index)
  }

  const first = steps[0]?.value ?? 0
  const stages = steps.map((step, index) => ({
    ...step,
    share: first > 0 ? Math.min(1, Math.max(0, step.value / first)) : 0,
    fill: step.color ?? color ?? defaultColors[index % defaultColors.length],
    // A single color fades toward the end of the funnel so stages stay distinct.
    opacity: color && !step.color ? 1 - index * (0.6 / Math.max(steps.length - 1, 1)) : 1,
  }))

  return (
    <>
      <div
        data-slot="funnel-flow"
        className="flex w-full items-stretch"
        style={{ height }}
        onMouseLeave={() => setActive(null)}
      >
        {stages.map((stage, index) => {
          const next = stages[index + 1]
          const dimmed = active !== null && active !== index
          const neckDimmed = active !== null && active !== index && active !== index + 1
          const gradient = `${id}-${index}`
          return (
            <React.Fragment key={stage.name}>
              <div
                data-slot="funnel-stage"
                data-active={active === index || undefined}
                onMouseEnter={() => setActive(index)}
                className="relative flex min-w-0 flex-1 items-center transition-opacity duration-200"
                style={{ opacity: dimmed ? 0.35 : 1 }}
              >
                <div
                  className={cn(
                    "w-full transition-[height] duration-500 ease-out",
                    index === 0 && "rounded-l-lg",
                    index === stages.length - 1 && "rounded-r-lg"
                  )}
                  style={{
                    height: `${round(stage.share * 100)}%`,
                    minHeight: 4,
                    backgroundColor: stage.fill,
                    opacity: stage.opacity,
                  }}
                />
                {showPercentages ? (
                  <span className="bg-background/90 text-foreground ring-foreground/10 pointer-events-none absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full px-2 py-0.5 text-[11px] font-medium tabular-nums shadow-xs ring-1 backdrop-blur-sm">
                    {formatNumber(stage.share, { format: "percent", maximumFractionDigits: 0 })}
                  </span>
                ) : null}
              </div>
              {next ? (
                <svg
                  aria-hidden="true"
                  data-slot="funnel-neck"
                  viewBox="0 0 1 1"
                  preserveAspectRatio="none"
                  className="h-full shrink-0 transition-opacity duration-200"
                  style={{ width: neckWidth, opacity: neckDimmed ? 0.35 : 1 }}
                >
                  <defs>
                    <linearGradient id={gradient} x1="0" y1="0" x2="1" y2="0">
                      <stop offset="0" stopColor={stage.fill} stopOpacity={stage.opacity} />
                      <stop offset="1" stopColor={next.fill} stopOpacity={next.opacity} />
                    </linearGradient>
                  </defs>
                  <path
                    d={neckPath(stage.share, next.share, shape)}
                    fill={`url(#${gradient})`}
                    className="transition-[d] duration-500 ease-out"
                  />
                </svg>
              ) : null}
            </React.Fragment>
          )
        })}
      </div>
      {showLabels ? (
        <div
          data-slot="funnel-labels"
          className="grid gap-2"
          style={{ gridTemplateColumns: `repeat(${stages.length}, minmax(0, 1fr))` }}
        >
          {stages.map((stage, index) => (
            <div
              key={stage.name}
              data-active={active === index || undefined}
              onMouseEnter={() => setActive(index)}
              onMouseLeave={() => setActive(null)}
              className={cn(
                "flex min-w-0 flex-col gap-0.5 rounded-lg border px-2.5 py-2 transition-[opacity,border-color] duration-200",
                active !== null && active !== index && "opacity-50",
                active === index && "border-foreground/20"
              )}
            >
              <span className="text-muted-foreground flex items-center gap-1.5 text-xs">
                <span
                  aria-hidden="true"
                  className="size-2 shrink-0 rounded-full"
                  style={{ backgroundColor: stage.fill, opacity: stage.opacity }}
                />
                <span className="truncate">{stage.name}</span>
              </span>
              <span className="truncate text-sm font-semibold tabular-nums">
                {valueFormatter(stage.value)}
              </span>
            </div>
          ))}
        </div>
      ) : null}
    </>
  )
}

/** Step-by-step conversion, as stacked bars with drop-off or as a flow of tapering stages. */
function FunnelChart({
  steps,
  valueFormatter = (value) => formatNumber(value),
  color,
  showDropoff = true,
  variant = "bars",
  shape = "eased",
  height = 160,
  neckWidth = 24,
  showPercentages = true,
  showLabels = true,
  activeIndex,
  onActiveIndexChange,
  className,
  ...props
}: FunnelChartProps) {
  return (
    <div
      data-slot="funnel-chart"
      data-variant={variant}
      className={cn("flex flex-col", variant === "flow" ? "gap-3" : "gap-1", className)}
      {...props}
    >
      {variant === "flow" ? (
        <FunnelFlow
          steps={steps}
          valueFormatter={valueFormatter}
          color={color}
          shape={shape}
          height={height}
          neckWidth={neckWidth}
          showPercentages={showPercentages}
          showLabels={showLabels}
          activeIndex={activeIndex}
          onActiveIndexChange={onActiveIndexChange}
        />
      ) : (
        <FunnelBars
          steps={steps}
          valueFormatter={valueFormatter}
          color={color ?? "var(--chart-1)"}
          showDropoff={showDropoff}
        />
      )}
    </div>
  )
}

export { FunnelChart }

import * as React from "react"
import { Minus, TrendingDown, TrendingUp } from "lucide-react"

import { cn } from "@/lib/utils"
import { formatDelta } from "@/registry/dashboardcn/lib/format"

export type DeltaDirection = "up" | "down" | "flat"

export function getDeltaDirection(delta: number | undefined): DeltaDirection {
  if (delta === undefined || delta === 0 || !Number.isFinite(delta)) return "flat"
  return delta > 0 ? "up" : "down"
}

const directionIcon: Record<DeltaDirection, React.ElementType> = {
  up: TrendingUp,
  down: TrendingDown,
  flat: Minus,
}

export interface DeltaBadgeProps extends React.ComponentProps<"span"> {
  /** Fractional change, e.g. 0.124 for +12.4%. */
  delta: number
  /** Treat a decrease as good and an increase as bad (churn, latency, errors). */
  invert?: boolean
  variant?: "outline" | "soft" | "text"
  showIcon?: boolean
}

function DeltaBadge({
  delta,
  invert = false,
  variant = "outline",
  showIcon = true,
  className,
  children,
  ...props
}: DeltaBadgeProps) {
  const direction = getDeltaDirection(delta)
  const positive = direction === "flat" ? null : (direction === "up") !== invert
  const Icon = directionIcon[direction]

  return (
    <span
      data-slot="delta-badge"
      data-direction={direction}
      data-positive={positive}
      className={cn(
        "inline-flex items-center gap-1 text-xs font-medium tabular-nums",
        variant === "outline" && "rounded-md border px-1.5 py-0.5",
        variant === "soft" && "rounded-md px-1.5 py-0.5",
        variant === "soft" && positive === true && "bg-emerald-500/10",
        variant === "soft" && positive === false && "bg-red-500/10",
        variant === "soft" && positive === null && "bg-muted",
        positive === true && "text-emerald-600 dark:text-emerald-400",
        positive === false && "text-red-600 dark:text-red-400",
        positive === null && "text-muted-foreground",
        className
      )}
      {...props}
    >
      {showIcon ? <Icon className="size-3" aria-hidden="true" /> : null}
      {children ?? formatDelta(delta)}
    </span>
  )
}

export { DeltaBadge }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

/** Values at or above this are abbreviated by default. */
export const DEFAULT_COMPACT_FROM = 100_000

export interface MetricValueProps extends Omit<React.ComponentProps<"span">, "children"> {
  /** Strings render as-is. */
  value: number | string
  format?: NumberFormat
  currency?: string
  maximumFractionDigits?: number
  /** Values at or above this are abbreviated (e.g. $158K) with the full value in a tooltip. Set to Infinity to always show the full value. */
  compactFrom?: number
  /** Text after the number, e.g. a unit. */
  suffix?: React.ReactNode
}

/** A formatted number. Large values are abbreviated and reveal the full value on hover. */
function MetricValue({
  value,
  format,
  currency,
  maximumFractionDigits,
  compactFrom = DEFAULT_COMPACT_FROM,
  suffix,
  className,
  ...props
}: MetricValueProps) {
  const classes = cn("tabular-nums", className)

  if (typeof value !== "number") {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {value}
        {suffix}
      </span>
    )
  }

  const full = formatNumber(value, { format, currency, maximumFractionDigits })
  const abbreviate = format !== "percent" && Math.abs(value) >= compactFrom
  if (!abbreviate) {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {full}
        {suffix}
      </span>
    )
  }

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <span
            data-slot="metric-value"
            data-compact=""
            className={cn(classes, "cursor-default")}
            {...props}
          >
            {formatNumber(value, { format, currency, compact: true })}
            {suffix}
          </span>
        </TooltipTrigger>
        <TooltipContent className="tabular-nums">
          {full}
          {suffix}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}

export { MetricValue }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
  /** Abbreviate large values, e.g. "$158K" instead of "$158,143". */
  compact?: boolean
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(158143, { format: "currency", compact: true }) -> "$158K"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
    compact = false,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  // Compact values keep three significant digits: $158K, $1.23M, 41.2K.
  const compactOptions: Intl.NumberFormatOptions = compact
    ? maximumFractionDigits === undefined
      ? { notation: "compact", maximumSignificantDigits: 3 }
      : { notation: "compact", maximumFractionDigits }
    : {}
  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
        ...compactOptions,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
        ...compactOptions,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
